// The text every mirrored module shares: its first line, the type-only
// imports from `@pcvl/schema` a Compiled Schema and its Standalone marker are
// written with, and its Compiled Schemas' class names.

import {
  ISSUE_CLASS_NAME,
  RESULT_TYPE_NAME,
  SCHEMA_BRAND_NAME,
  SCHEMA_TYPE_NAME,
  STANDALONE_BRAND_NAME,
  STANDALONE_MARKER_TYPE_NAME,
  STANDARD_SCHEMA_PROPS_TYPE_NAME,
} from '../frame/consts.js';

/** The first line of every file the compiler writes. */
export const GENERATED_HEADER =
  '// @generated by @pcvl/compiler. Do not edit: run `pvl compile` to regenerate.' as const;

/** What a module's Compiled Schemas' class names start with, before their index in source order: `PvlCompiledSchema0`. */
export const COMPILED_SCHEMA_CLASS_NAME_PREFIX = 'PvlCompiledSchema' as const;

/**
 * The import a module holding a Compiled Schema gets, aliasing
 * `@pcvl/schema`'s exports so they can't clash with the module's own. It is
 * type-only: a Compiled Schema implements `Schema` rather than extending a
 * class, so it needs nothing from `@pcvl/schema` at runtime.
 */
export const COMPILED_SCHEMA_IMPORT =
  `import type { Issue as ${ISSUE_CLASS_NAME}, Result as ${RESULT_TYPE_NAME}, SCHEMA_BRAND as ${SCHEMA_BRAND_NAME}, Schema as ${SCHEMA_TYPE_NAME}, StandaloneMarker as ${STANDALONE_MARKER_TYPE_NAME}, StandardSchemaProps as ${STANDARD_SCHEMA_PROPS_TYPE_NAME} } from '@pcvl/schema';` as const;

/**
 * The import a module holding a Compiled Schema marked `.standalone()` gets
 * besides `COMPILED_SCHEMA_IMPORT`, for the marker's brand it declares, so a
 * module with none imports nothing unused.
 */
export const STANDALONE_BRAND_IMPORT =
  `import type { STANDALONE_BRAND as ${STANDALONE_BRAND_NAME} } from '@pcvl/schema';` as const;
